cat >app/views/moderate/previews/show.html.erb <<'EOF'
<% content_for :title, "Preview · #{@quiz.title}" %>
<header class="preview-banner">
  <span>Moderator preview</span>
  <%= link_to "Back to quiz", moderate_quiz_path(@quiz) %>
</header>
<main class="play" data-preview>
  <div class="play__top">
    <span class="logo play__logo"><%= render "shared/logo" %></span>
    <span><%= @quiz.title %></span>
  </div>
  <% if @questions.empty? %>
    <div class="empty">No active questions to preview.</div>
  <% else %>
    <% @questions.each_with_index do |question, index| %>
      <template data-question>
        <div class="play-question__num">Question <%= index + 1 %> of <%= @questions.size %></div>
        <h1 class="play-question__body" tabindex="-1"><%= question.body %></h1>
        <div class="play-options">
          <% question.options.each_with_index do |option, i| %>
            <button type="button" class="play-option" data-correct="<%= option['correct'] %>">
              <span class="play-option__letter" aria-hidden="true"><%= option_letter(i) %></span>
              <span class="play-option__title"><%= option['text'] %></span>
              <span class="play-option__mark" hidden>✓ Correct</span>
            </button>
          <% end %>
        </div>
        <div class="play-status" role="status" hidden></div>
      </template>
    <% end %>
    <div class="play__body--top" data-current></div>
    <section class="card result-card" hidden>
      <p class="play-question__num">Preview complete</p>
      <h1 class="result-card__score" tabindex="-1">Score: <span data-points>0</span>/<%= @questions.size %></h1>
    </section>
    <div class="buttons mt-2">
      <button type="button" class="btn btn--pink" data-next hidden>Next question</button>
      <button type="button" class="btn btn--ghost" data-restart>Start over</button>
    </div>
    <noscript>Enable JavaScript to try the player preview.</noscript>
  <% end %>
</main>
EOF
