// Only the current question index and running total live in this tab. Nothing
// is submitted, put in browser storage, or carried over to a fresh preview.
function runPreview(player) {
  const questions = player.querySelectorAll("template[data-question]");
  if (!questions.length) return;

  const current = player.querySelector("[data-current]");
  const result = player.querySelector(".result-card");
  const next = player.querySelector("[data-next]");
  let index = 0;
  let points = 0;

  function showQuestion() {
    current.replaceChildren(questions[index].content.cloneNode(true));
    result.hidden = true;
    next.hidden = true;
    next.textContent = index + 1 === questions.length ? "See score" : "Next question";
  }

  current.addEventListener("click", event => {
    const pick = event.target.closest(".play-option");
    if (!pick || pick.disabled) return;
    const right = pick.dataset.correct === "true";
    if (right) points++;
    pick.classList.add("is-picked");
    pick.parentElement.classList.add("is-locked", "is-revealed");
    for (const option of current.querySelectorAll(".play-option")) {
      option.disabled = true;
      if (option.dataset.correct === "true") {
        option.classList.add("is-correct");
        option.querySelector(".play-option__mark").hidden = false;
      }
    }
    const status = current.querySelector("[role=status]");
    status.hidden = false;
    status.classList.add(right ? "play-status--correct" : "play-status--wrong");
    status.textContent = right ? "Correct!" : "Wrong!";
    next.hidden = false;
    next.focus();
  });

  next.addEventListener("click", () => {
    index++;
    if (index < questions.length) {
      showQuestion();
      current.querySelector("h1").focus();
    } else {
      current.replaceChildren();
      next.hidden = true;
      result.querySelector("[data-points]").textContent = points;
      result.hidden = false;
      result.querySelector("h1").focus();
    }
  });

  player.querySelector("[data-restart]").addEventListener("click", () => {
    index = 0;
    points = 0;
    showQuestion();
    current.querySelector("h1").focus();
  });
  showQuestion();
}

runPreview(document.querySelector("[data-preview]"));
